package com.rikkeibank.account.controller; import com.rikkeibank.account.dto.BankAccountRequest; import com.rikkeibank.account.model.BankAccount; import com.rikkeibank.account.service.BankAccountService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/accounts") public class BankAccountController{private final BankAccountService s;public BankAccountController(BankAccountService s){this.s=s;}@GetMapping("/me") @PreAuthorize("hasRole('CUSTOMER')") public List<BankAccount> mine(@AuthenticationPrincipal Jwt jwt){return s.mine(jwt.getSubject());}@GetMapping @PreAuthorize("hasRole('ADMIN')") public List<BankAccount> all(){return s.all();}@GetMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public BankAccount one(@PathVariable Long id){return s.find(id);}@PostMapping @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<BankAccount> create(@Valid @RequestBody BankAccountRequest r){return ResponseEntity.status(201).body(s.create(r));}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public BankAccount update(@PathVariable Long id,@Valid @RequestBody BankAccountRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
